 fx.innerHTML=`<div class="account-fx-card"><span class="eyebrow">QUEDA</span>${sprite(m.species,'vanishing-mon')}<strong>${esc(mon(m.species).name)}</strong><p>Removido permanentemente da coleção.</p>${delta||coins?`<p>Recompensas descontadas: ${delta} XP · − ${money(Math.abs(coins))}</p>`:''}</div>`;document.body.append(fx);paint();
