function handleAttack(id,extra={}){return playTurn({move:id,...extra});}
function attack(id){const b=S.battle,a=E.byMove[id];if(!a||!E.usable(b,'player').includes(id))return;if(E.ineffectiveReason(b,'player',id))return handleAttack(id);if(['block','copy'].includes(a.effect)){const foe=E.active(b,'enemy');modal(`<h2>${a.effect==='copy'?'Copiar qual movimento?':'Bloquear qual '+(a.targetKind==='attack'?'ataque':'habilidade')+'?'}</h2><div class="settings-list">${E.targetMoves(b,'player',a).map(x=>button(esc(E.byMove[x].name)+(a.effect==='copy'?` · ${foe.pp[x]} usos restantes`:''),'attack-target',`data-move="${id}" data-target-move="${x}"`)).join('')}</div>`);return;}
 if(a.effect==='portal'||a.effect==='force'&&a.choose){const side=a.effect==='portal'?'player':'enemy',current=side==='player'?b.pi:b.ei;modal(`<h2>Escolha o Mon que vai entrar</h2><div class="switch-grid">${E.alive(b,side).filter(x=>x.i!==current).map(({m,i})=>`<button class="switch-option" data-action="attack-target" data-move="${id}" data-target="${i}">${sprite(m.species)}${esc(mon(m.species).name)}</button>`).join('')}</div>`);return;}return handleAttack(id);}
